#!/bin/sh
# embute a página (web/**) e as DLLs do WebView2 no Koru.exe
cd "$(dirname "$0")"
RES=$(cd web && find . -type f | sed 's#^\./##; s#.*#-resource:web/&,web/&#' | tr '\n' ' ')
mcs -codepage:utf8 -target:winexe -sdk:4.5 -optimize+ -platform:anycpu -win32icon:jogo.ico -out:"Koru.exe" -r:System.Web.Extensions.dll -r:System.Windows.Forms.dll -r:System.Drawing.dll -r:System.Core.dll -r:System.Web.dll -r:System.IO.Compression.dll -r:System.IO.Compression.FileSystem.dll -r:System.Management.dll -r:Microsoft.VisualBasic.dll -r:Microsoft.Web.WebView2.Core.dll -r:Microsoft.Web.WebView2.WinForms.dll $RES -resource:logo256.png,logo.png -resource:sym.png,sym.png -resource:config.json,config.json -resource:Microsoft.Web.WebView2.Core.dll,Microsoft.Web.WebView2.Core.dll -resource:Microsoft.Web.WebView2.WinForms.dll,Microsoft.Web.WebView2.WinForms.dll -resource:WebView2Loader.x64.dll,WebView2Loader.x64.dll -resource:WebView2Loader.x86.dll,WebView2Loader.x86.dll Http.cs Central.*.cs WebHost.cs WebHost.Player.cs WebHost.Mini.cs WebHost.Hotkey.cs AutoConfig.cs FolderPicker.cs
